type AttrAttrPayload struct {
	Name  string
	Value string
}

func attrAttrPayloadFromValue(l *Bindings, v eval.Value) AttrAttrPayload {
	r := l.env.Record(v)
	return AttrAttrPayload{
		Name:  r.Get(l.name).Text(),
		Value: r.Get(l.value).Text(),
	}
}

func (x AttrAttrPayload) toValue(l *Bindings) eval.Value {
	return l.attrAttrPayloadShape.New(
		eval.Text(x.Name),
		eval.Text(x.Value),
	)
}

// Ref returns x as a value of the environment of l.
func (x AttrAttrPayload) Ref(l *Bindings) AttrAttrPayloadRef {
	return AttrAttrPayloadRef{ref{l, x.toValue(l)}}
}

// AttrAttrPayloadRef is a AttrAttrPayload as a script holds it. It converts only the fields
// that are read, and goes back to a script as it is.
type AttrAttrPayloadRef struct{ ref }

// Load converts all of x.
func (x AttrAttrPayloadRef) Load() AttrAttrPayload { return attrAttrPayloadFromValue(x.b, x.v) }

func (x AttrAttrPayloadRef) Name() string {
	l := x.b
	return l.attrAttrPayloadShape.Field(x.v, 0).Text()
}

func (x AttrAttrPayloadRef) Value() string {
	l := x.b
	return l.attrAttrPayloadShape.Field(x.v, 1).Text()
}

