type Keyed struct {
	Attrs    []Attr
	Children []Child
	Tag      string
}

func keyedFromValue(l *Bindings, v eval.Value) Keyed {
	r := l.env.Record(v)
	return Keyed{
		Attrs:    host.ListFrom(r.Get(l.attrs), func(v eval.Value) Attr { return attrFromValue(l, v) }),
		Children: host.ListFrom(r.Get(l.children), func(v eval.Value) Child { return childFromValue(l, v) }),
		Tag:      r.Get(l.tag).Text(),
	}
}

func (x Keyed) toValue(l *Bindings) eval.Value {
	return l.keyedShape.New(
		host.ListTo(x.Attrs, func(x Attr) eval.Value { return x.toValue(l) }),
		host.ListTo(x.Children, func(x Child) eval.Value { return x.toValue(l) }),
		eval.Text(x.Tag),
	)
}

// Ref returns x as a value of the environment of l.
func (x Keyed) Ref(l *Bindings) KeyedRef { return KeyedRef{ref{l, x.toValue(l)}} }

// KeyedRef is a Keyed as a script holds it. It converts only the fields
// that are read, and goes back to a script as it is.
type KeyedRef struct{ ref }

// Load converts all of x.
func (x KeyedRef) Load() Keyed { return keyedFromValue(x.b, x.v) }

func (x KeyedRef) Attrs() host.ListRef[AttrRef] {
	l := x.b
	return host.NewListRef(l.keyedShape.Field(x.v, 0), func(v eval.Value) AttrRef { return AttrRef{ref{l, v}} })
}

func (x KeyedRef) Children() host.ListRef[ChildRef] {
	l := x.b
	return host.NewListRef(l.keyedShape.Field(x.v, 1), func(v eval.Value) ChildRef { return ChildRef{ref{l, v}} })
}

func (x KeyedRef) Tag() string {
	l := x.b
	return l.keyedShape.Field(x.v, 2).Text()
}

type Child struct {
	Key  string
	Node Node
}

func childFromValue(l *Bindings, v eval.Value) Child {
	r := l.env.Record(v)
	return Child{
		Key:  r.Get(l.key).Text(),
		Node: nodeFromValue(l, r.Get(l.node)),
	}
}

func (x Child) toValue(l *Bindings) eval.Value {
	return l.childShape.New(
		eval.Text(x.Key),
		x.Node.toValue(l),
	)
}

// Ref returns x as a value of the environment of l.
func (x Child) Ref(l *Bindings) ChildRef { return ChildRef{ref{l, x.toValue(l)}} }

// ChildRef is a Child as a script holds it. It converts only the fields
// that are read, and goes back to a script as it is.
type ChildRef struct{ ref }

// Load converts all of x.
func (x ChildRef) Load() Child { return childFromValue(x.b, x.v) }

func (x ChildRef) Key() string {
	l := x.b
	return l.childShape.Field(x.v, 0).Text()
}

func (x ChildRef) Node() NodeRef {
	l := x.b
	return NodeRef{ref{l, l.childShape.Field(x.v, 1)}}
}

// Bindings make and read the values of the interface's types in the
// environment that Load checked the script in: they hold the IDs of
// the interface's record labels and tags there, which values hold, the
// shapes of its records, and the environment, which reads records.
type Bindings struct {
	env                      *eval.Environment
	animationFrame           label.ID
	attr                     label.ID
	attrs                    label.ID
	body                     label.ID
	bool                     label.ID
	bytes                    label.ID
	children                 label.ID
	cmds                     label.ID
	el                       label.ID
	error                    label.ID
	event                    label.ID
	every                    label.ID
	expect                   label.ID
	false                    label.ID
	headers                  label.ID
	http                     label.ID
	init                     label.ID
	json                     label.ID
	key                      label.ID
	keyed                    label.ID
	list                     label.ID
	max                      label.ID
	method                   label.ID
	min                      label.ID
	model                    label.ID
	ms                       label.ID
	msg                      label.ID
	name                     label.ID
	node                     label.ID
	now                      label.ID
	null                     label.ID
	number                   label.ID
	object                   label.ID
	ok                       label.ID
	on                       label.ID
	onCheck                  label.ID
	onClick                  label.ID
	onInput                  label.ID
	onSubmit                 label.ID
	prop                     label.ID
	randomFloat              label.ID
	randomInt                label.ID
	status                   label.ID
	style                    label.ID
	subscriptions            label.ID
	tag                      label.ID
	text                     label.ID
	true                     label.ID
	update                   label.ID
	url                      label.ID
	value                    label.ID
	view                     label.ID
	appShape                 *eval.Shape
	memberShape              *eval.Shape
	stepShape                *eval.Shape
	requestShape             *eval.Shape
	responseBytesShape       *eval.Shape
	headerShape              *eval.Shape
	responseJsonShape        *eval.Shape
	responseTextShape        *eval.Shape
	cmdRandomIntPayloadShape *eval.Shape
	subEveryPayloadShape     *eval.Shape
	elementShape             *eval.Shape
	attrAttrPayloadShape     *eval.Shape
	attrOnPayloadShape       *eval.Shape
	attrPropPayloadShape     *eval.Shape
	attrStylePayloadShape    *eval.Shape
	keyedShape               *eval.Shape
	childShape               *eval.Shape
}

func newBindings(env *eval.Environment) *Bindings {
	l := &Bindings{
		env:            env,
		animationFrame: env.Label("animation-frame"),
		attr:           env.Label("attr"),
		attrs:          env.Label("attrs"),
		body:           env.Label("body"),
		bool:           env.Label("bool"),
		bytes:          env.Label("bytes"),
		children:       env.Label("children"),
		cmds:           env.Label("cmds"),
		el:             env.Label("el"),
		error:          env.Label("error"),
		event:          env.Label("event"),
		every:          env.Label("every"),
		expect:         env.Label("expect"),
		false:          env.Label("false"),
		headers:        env.Label("headers"),
		http:           env.Label("http"),
		init:           env.Label("init"),
		json:           env.Label("json"),
		key:            env.Label("key"),
		keyed:          env.Label("keyed"),
		list:           env.Label("list"),
		max:            env.Label("max"),
		method:         env.Label("method"),
		min:            env.Label("min"),
		model:          env.Label("model"),
		ms:             env.Label("ms"),
		msg:            env.Label("msg"),
		name:           env.Label("name"),
		node:           env.Label("node"),
		now:            env.Label("now"),
		null:           env.Label("null"),
		number:         env.Label("number"),
		object:         env.Label("object"),
		ok:             env.Label("ok"),
		on:             env.Label("on"),
		onCheck:        env.Label("on-check"),
		onClick:        env.Label("on-click"),
		onInput:        env.Label("on-input"),
		onSubmit:       env.Label("on-submit"),
		prop:           env.Label("prop"),
		randomFloat:    env.Label("random-float"),
		randomInt:      env.Label("random-int"),
		status:         env.Label("status"),
		style:          env.Label("style"),
		subscriptions:  env.Label("subscriptions"),
		tag:            env.Label("tag"),
		text:           env.Label("text"),
		true:           env.Label("true"),
		update:         env.Label("update"),
		url:            env.Label("url"),
		value:          env.Label("value"),
		view:           env.Label("view"),
	}
	l.appShape = env.Shape(l.init, l.subscriptions, l.update, l.view)
	l.memberShape = env.Shape(l.key, l.value)
	l.stepShape = env.Shape(l.cmds, l.model)
	l.requestShape = env.Shape(l.body, l.expect, l.headers, l.method, l.url)
	l.responseBytesShape = env.Shape(l.body, l.headers, l.status)
	l.headerShape = env.Shape(l.name, l.value)
	l.responseJsonShape = env.Shape(l.body, l.headers, l.status)
	l.responseTextShape = env.Shape(l.body, l.headers, l.status)
	l.cmdRandomIntPayloadShape = env.Shape(l.max, l.min, l.msg)
	l.subEveryPayloadShape = env.Shape(l.ms, l.msg)
	l.elementShape = env.Shape(l.attrs, l.children, l.tag)
	l.attrAttrPayloadShape = env.Shape(l.name, l.value)
	l.attrOnPayloadShape = env.Shape(l.event, l.msg)
	l.attrPropPayloadShape = env.Shape(l.name, l.value)
	l.attrStylePayloadShape = env.Shape(l.name, l.value)
	l.keyedShape = env.Shape(l.attrs, l.children, l.tag)
	l.childShape = env.Shape(l.key, l.node)
	return l
}
